"}, {"path": "app/repository.py", "content": """"Repository layer (Section 10.5): persistence is isolated behind this
interface so it can be swapped for a real SQLAlchemy/SQLite backend
without touching the service layer â€” see docs/limitations.md for why
the demo uses an in-memory store instead."""

from __future__ import annotations

from datetime import datetime

from app.models import Link


class LinkRepository:
    def __init__(self) -> None:
        self._by_code: dict[str, Link] = {}

    def add(self, link: Link) -> Link:
        self._by_code[link.code] = link
        return link

    def get(self, code: str) -> Link | None:
        return self._by_code.get(code)

    def exists(self, code: str) -> bool:
        return code in self._by_code

    def deactivate(self, code: str) -> Link | None:
        link = self._by_code.get(code)
        if link is not None:
            link.is_active = False
        return link

    def record_click(self, code: str) -> None:
        link = self._by_code.get(code)
        if link is not None:
            link.click_count += 1

    def list_active(self, now: datetime) -> list[Link]:
        return [
            link for link in self._by_code.values()
            if link.is_active and (link.expires_at is None or link.expires_at > now)
        ]
