redirect, retrieve and health-check. Dependency injection via FastAPI
Depends; no module-level singleton for the repository/service â€” a
fresh app() factory wires a fresh in-memory store per instance so tests
never leak state between cases.
"""

from __future__ import annotations

from datetime import datetime
from uuid import uuid4

from fastapi import Depends, FastAPI, HTTPException, Request
from fastapi.responses import JSONResponse, RedirectResponse
from pydantic import BaseModel, Field

from app.repository import LinkRepository
from app.service import AliasUnavailableError, InvalidTargetUrlError, LinkService


class CreateLinkRequest(BaseModel):
    target_url: str = Field(..., max_length=2048)
    custom_alias: str | None = None
    expires_at: datetime | None = None
    metadata: dict = Field(default_factory=dict)


class LinkResponse(BaseModel):
    code: str
    target_url: str
    is_custom: bool
    created_at: datetime
    expires_at: datetime | None
    is_active: bool
    click_count: int


def _to_response(link) -> LinkResponse:  # noqa: ANN001
    return LinkResponse(
        code=link.code, target_url=link.target_url, is_custom=link.is_custom,
        created_at=link.created_at, expires_at=link.expires_at,
        is_active=link.is_active, click_count=link.click_count,
    )


def create_app() -> FastAPI:
    app = FastAPI(title="URL Shortener", version="0.1.0")
    repository = LinkRepository()
    service = LinkService(repository=repository)

    def get_service() -> LinkService:
        return service

    @app.exception_handler(HTTPException)
    async def http_exception_handler(request: Request, exc: HTTPException) -> JSONResponse:
        """Uniform error envelope (Section 10.4): {error: {code, message, request_id}}."""
        detail = exc.detail if isinstance(exc.detail, dict) else {"code": "error", "message": str(exc.detail)}
        return JSONResponse(status_code=exc.status_code, content={"error": {**detail, "request_id": str(uuid4())}})

    @app.get("/healthz")
    async def healthz() -> dict:
        return {"status": "ok"}

    @app.get("/readyz")
    async def readyz() -> dict:
        return {"status": "ready"}

    @app.post("/api/v1/links", status_code=201, response_model=LinkResponse)
    async def create_link(body: CreateLinkRequest, svc: LinkService = Depends(get_service)):
        try:
            link = svc.create_link(
                target_url=body.target_url, custom_alias=body.custom_alias,
                expires_at=body.expires_at, metadata=body.metadata,
            )
        except InvalidTargetUrlError as exc:
            raise HTTPException(status_code=400, detail={"code": "invalid_target_url", "message": str(exc)}) from exc
        except AliasUnavailableError as exc:
            raise HTTPException(status_code=409, detail={"code": "alias_unavailable", "message": str(exc)}) from exc
        return _to_response(link)

    @app.get("/api/v1/links/{code}", response_model=LinkResponse)
    async def get_link(code: str, svc: LinkService = Depends(get_service)):
        link = svc.get_link(code)
        if link is None:
            raise HTTPException(status_code=404, detail={"code": "not_found", "message": "link not found"})
        return _to_response(link)

    @app.delete("/api/v1/links/{code}", status_code=204)
    async def delete_link(code: str, svc: LinkService = Depends(get_service)) -> None:
        link = svc.deactivate(code)
        if link is None:
            raise HTTPException(status_code=404, detail={"code": "not_found", "message": "link not found"})

    @app.get("/{code}")
    async def redirect(code: str, svc: LinkService = Depends(get_service)):
        link = svc.resolve_for_redirect(code)
        if link is None:
            raise HTTPException(status_code=404, detail={"code": "not_found", "message": "link not found or expired"})
        return RedirectResponse(url=link.target_url, status_code=302)

    return app


app = create_app()
